  39	function detachPrecommitLeaseHeartbeat(
  40	  taskId: string,
  41	): PrecommitLeaseHeartbeat | undefined {
  42	  const heartbeat = precommitLeaseHeartbeats.get(taskId);
  43	  if (!heartbeat) return undefined;
  44	  heartbeat.stopped = true;
  45	  if (heartbeat.timer) clearTimeout(heartbeat.timer);
  46	  precommitLeaseHeartbeats.delete(taskId);
