  59	function startPrecommitLeaseHeartbeat(
  60	  db: Adapter,
  61	  taskId: string,
  62	  initialLeaseValue: string,
  63	): void {
  64	  detachPrecommitLeaseHeartbeat(taskId);
  65	  const heartbeat: PrecommitLeaseHeartbeat = {
  66	    stopped: false,
  67	    timer: null,
  68	    leaseValue: initialLeaseValue,
  69	    inFlight: null,
