 12	/**
 13	 * Returns only DataFn protocol resource selectors. Application records and
 14	 * filters may legitimately contain fields named `resource` or `resources`;
 15	 * recursively inspecting arbitrary payload data would treat those values as
 16	 * routing or authorization input.
 17	 */
 18	export function collectDatafnStructuralResources(payload: unknown): Set<string> {
 19	  const found = new Set<string>();
 20	  if (Array.isArray(payload)) {
 21	    for (const entry of payload) addResourceSelectors(entry, found);
 22	    return found;
 23	  }
 24	  addResourceSelectors(payload, found);
 25	  if (!payload || typeof payload !== "object") return found;
 26	
 27	  const record = payload as Record<string, unknown>;
 28	  if (Array.isArray(record.steps)) {
 29	    for (const step of record.steps) {
 30	      addResourceSelectors(step, found);
 31	      if (!step || typeof step !== "object" || Array.isArray(step)) continue;
 32	      const structuralStep = step as Record<string, unknown>;
 33	      addResourceSelectors(structuralStep.query, found);
 34	      addResourceSelectors(structuralStep.mutation, found);
 35	    }
 36	  }
 37	  if (Array.isArray(record.mutations)) {
 38	    for (const mutation of record.mutations) {
 39	      addResourceSelectors(mutation, found);
 40	    }
 41	  }
 42	  return found;
 43	}
