 66	async function dynamicNamespaceTables(
 67	  pool: MigrationSqlPool,
 68	): Promise<DynamicNamespaceTable[]> {
 69	  const result = await pool.query<{
 70	    table_name: string;
 71	    namespace_column: "__ns" | "namespace";
 72	  }>(
 73	    `SELECT table_name,
 74	            CASE WHEN bool_or(column_name = '__ns') THEN '__ns'
 75	                 ELSE 'namespace' END AS namespace_column
 76	       FROM information_schema.columns
 77	      WHERE table_schema = 'public'
 78	      GROUP BY table_name
 79	     HAVING bool_or(column_name = '__ns')
 80	         OR (left(table_name, 9) = '__datafn_' AND
 81	             bool_or(column_name = 'namespace'))
 82	      ORDER BY table_name`,
 83	  );
 84	  return result.rows
 85	    .filter(
 86	      (row) =>
 87	        !regionalTables.includes(row.table_name as (typeof regionalTables)[number]),
 88	    )
 89	    .map((row) => ({
 90	      tableName: row.table_name,
 91	      namespaceColumn: row.namespace_column,
 92	    }));
 93	}
