182	async function digest(bytes: Uint8Array): Promise<string> {
183	  const copy = new Uint8Array(bytes.byteLength);
184	  copy.set(bytes);
185	  return [...new Uint8Array(await crypto.subtle.digest("SHA-256", copy.buffer))]
186	    .map((byte) => byte.toString(16).padStart(2, "0"))
187	    .join("");
188	}
