  4	CREATE OR REPLACE FUNCTION skillplane_fence_workspace_migration_write()
  5	RETURNS trigger
  6	LANGUAGE plpgsql
  7	AS $$
  8	DECLARE
  9	  old_workspace_id text;
 10	  new_workspace_id text;
 11	  affected_workspace_id text;
 12	  cleanup_workspace_id text;
 13	  fence_epoch bigint;
 14	BEGIN
 15	  old_workspace_id := COALESCE(
 16	    to_jsonb(OLD) ->> 'workspace_id',
 17	    to_jsonb(OLD) ->> '__ns',
 18	    to_jsonb(OLD) ->> 'namespace'
 19	  );
 20	  new_workspace_id := COALESCE(
 21	    to_jsonb(NEW) ->> 'workspace_id',
 22	    to_jsonb(NEW) ->> '__ns',
 23	    to_jsonb(NEW) ->> 'namespace'
 24	  );
 25	  cleanup_workspace_id := current_setting(
 26	    'skillplane.workspace_migration_cleanup',
 27	    true
 28	  );
 29	
 30	  IF TG_TABLE_NAME IN (
 31	    'regional_projection_outbox',
 32	    '__datafn_permission_directory_outbox'
 33	  ) AND TG_OP IN ('UPDATE', 'DELETE') THEN
 34	    IF TG_OP = 'DELETE' THEN RETURN OLD; END IF;
 35	    RETURN NEW;
 36	  END IF;
 37	
 38	  FOREACH affected_workspace_id IN ARRAY ARRAY[
 39	    old_workspace_id,
 40	    new_workspace_id
 41	  ]
 42	  LOOP
 43	    CONTINUE WHEN affected_workspace_id IS NULL;
 44	    CONTINUE WHEN cleanup_workspace_id IS NOT DISTINCT FROM affected_workspace_id;
 45	
 46	    IF current_setting('transaction_isolation') IN ('repeatable read', 'serializable') THEN
 47	      INSERT INTO regional_workspace_migration_fences
 48	        (workspace_id, source_epoch)
 49	      VALUES (affected_workspace_id, 0)
 50	      ON CONFLICT (workspace_id)
 51	      DO UPDATE SET workspace_id = EXCLUDED.workspace_id
 52	      RETURNING source_epoch INTO fence_epoch;
 53	    ELSE
 54	      SELECT source_epoch INTO fence_epoch
 55	        FROM regional_workspace_migration_fences
 56	       WHERE workspace_id = affected_workspace_id;
 57	    END IF;
