  1	function addResourceSelectors(value: unknown, found: Set<string>): void {
  2	  if (!value || typeof value !== "object" || Array.isArray(value)) return;
  3	  const record = value as Record<string, unknown>;
  4	  if (typeof record.resource === "string") found.add(record.resource);
  5	  if (Array.isArray(record.resources)) {
  6	    for (const resource of record.resources) {
  7	      if (typeof resource === "string") found.add(resource);
  8	    }
  9	  }
 10	}
