  5	CREATE OR REPLACE FUNCTION skillplane_fence_workspace_migration_write()
  6	RETURNS trigger
  7	LANGUAGE plpgsql
  8	AS $$
  9	DECLARE
 10	  old_workspace_id text;
 11	  new_workspace_id text;
 12	  affected_workspace_id text;
 13	  cleanup_workspace_id text;
 14	  fence_epoch bigint;
 15	BEGIN
 16	  old_workspace_id := COALESCE(
 17	    to_jsonb(OLD) ->> 'workspace_id',
 18	    to_jsonb(OLD) ->> '__ns'
 19	  );
 20	  new_workspace_id := COALESCE(
 21	    to_jsonb(NEW) ->> 'workspace_id',
 22	    to_jsonb(NEW) ->> '__ns'
 23	  );
 24	  cleanup_workspace_id := current_setting(
 25	    'skillplane.workspace_migration_cleanup',
 26	    true
 27	  );
 28	
 29	  -- Enqueueing is still fenced. Only acknowledgements and retry bookkeeping
 30	  -- may change after quiescence, so the final retained snapshot cannot omit a
 31	  -- newly admitted workspace event.
 32	  IF TG_TABLE_NAME IN (
 33	    'regional_projection_outbox',
 34	    '__datafn_permission_directory_outbox'
 35	  ) AND TG_OP IN ('UPDATE', 'DELETE') THEN
 36	    IF TG_OP = 'DELETE' THEN RETURN OLD; END IF;
 37	    RETURN NEW;
 38	  END IF;
 39	
 40	  FOREACH affected_workspace_id IN ARRAY ARRAY[
 41	    old_workspace_id,
 42	    new_workspace_id
 43	  ]
 44	  LOOP
 45	    CONTINUE WHEN affected_workspace_id IS NULL;
 46	    CONTINUE WHEN cleanup_workspace_id IS NOT DISTINCT FROM affected_workspace_id;
 47	
 48	    IF current_setting('transaction_isolation') IN ('repeatable read', 'serializable') THEN
 49	      INSERT INTO regional_workspace_migration_fences
 50	        (workspace_id, source_epoch)
 51	      VALUES (affected_workspace_id, 0)
 52	      ON CONFLICT (workspace_id)
