211	function payloadReferencesInternalResource(
212	  payload: unknown,
213	  internalResourceNames: ReadonlySet<string>,
214	): boolean {
215	  if (internalResourceNames.size === 0) {
216	    return false;
217	  }
218	  if (Array.isArray(payload)) {
219	    return payload.some((entry) => payloadReferencesInternalResource(entry, internalResourceNames));
220	  }
221	  if (!payload || typeof payload !== "object") {
222	    return false;
223	  }
224	
225	  const record = payload as Record<string, unknown>;
226	  if (typeof record.resource === "string" && internalResourceNames.has(record.resource)) {
227	    return true;
228	  }
229	  if (
230	    Array.isArray(record.resources) &&
231	    record.resources.some((resource) => typeof resource === "string" && internalResourceNames.has(resource))
232	  ) {
233	    return true;
234	  }
235	
236	  for (const key of ["mutations", "queries", "steps", "operations"]) {
237	    if (Array.isArray(record[key]) && payloadReferencesInternalResource(record[key], internalResourceNames)) {
238	      return true;
239	    }
240	  }
241	  for (const key of ["query", "mutation", "payload"]) {
242	    if (record[key] && payloadReferencesInternalResource(record[key], internalResourceNames)) {
243	      return true;
244	    }
245	  }
246	
247	  return false;
248	}
